// src/legal/licenses.ts is generated by scripts/build-licenses.js: this fails when a dependency
// was added, removed or updated without re-running it. Jest runs in Node; the app's TypeScript
// config has no Node types, so type just what is used.
import { FONTS, OFL_TEXT, PACKAGES } from "../licenses";

/* eslint-disable @typescript-eslint/no-require-imports */
const fs = require("fs") as { readFileSync(file: string, encoding: "utf8"): string };
const path = require("path") as { join(...parts: string[]): string };
/* eslint-enable @typescript-eslint/no-require-imports */
declare const __dirname: string;

const ROOT = path.join(__dirname, "..", "..", "..");
const readJson = (...parts: string[]) => JSON.parse(fs.readFileSync(path.join(ROOT, ...parts), "utf8"));

test("every app dependency is listed, at its installed version (re-run: node scripts/build-licenses.js)", () => {
  const deps = Object.keys(readJson("package.json").dependencies).sort();
  expect(PACKAGES.map((p) => p.name)).toEqual(deps);
  for (const p of PACKAGES) expect(p.version).toBe(readJson("node_modules", ...p.name.split("/"), "package.json").version);
});

test("the bundled fonts carry the full SIL Open Font License", () => {
  expect(FONTS.map((f) => f.family)).toEqual(expect.arrayContaining(["Bricolage Grotesque", "Inter", "Lora", "Newsreader"]));
  expect(OFL_TEXT).toContain("SIL OPEN FONT LICENSE Version 1.1");
  expect(OFL_TEXT).toContain("OTHER DEALINGS IN THE FONT SOFTWARE.");
});
